/**
 * Utökad, unik text (≥500 ord) för /takbyte-<ort> på Storstockholms största kommuner
 * (sprint-offensiv-2026-09-28 punkt 3). Ersätter den korta mallgenererade texten i
 * service-location-combos.ts bara för dessa specifika tjänst+ort-kombinationer.
 * Bara allmänt belagd kunskap om kommunernas bebyggelse och taktyper — inga påhittade
 * projekt eller referenser. Lertegel och dubbelfalsat plåttak är belagda material (Vidars
 * beslut 2026-09-28). Eternit: vi samordnar sanering via behörig partner, utför inte själva.
 */
export interface ComboOverride {
  title: string;
  description: string;
  content: string[];
  /** Internlänkar ur briefens rad "Internlänkar (Hemsida lägger in, backlog 81)": adress och länktext, uppslagna vid importen. */
  links?: { to: string; label: string }[];
}

const PROCESS =
  "Processen är densamma oavsett kommun: en kostnadsfri takkontroll, en offert med fast pris och utförande enligt AMA. Vi lämnar 10 års garanti på utförandet. Vid takbyte och takomläggning lägger vi som standard underlagstak från MATAKI (Haloten PRO eller Haloten STEEL), med 30 års produktgaranti från tillverkaren på MATAKI:s villkor. Önskar du ett annat underlagstak står garantin för det i offerten. Du har en kontaktperson genom hela processen.";

const ROT =
  "Som privatperson kan du få ROT-avdrag på 30 % av arbetskostnaden, och vi drar av det direkt på fakturan.";

const INCLUDES = (name: string, prep: string) =>
  `Vad ingår i ett takbyte ${prep} ${name}? Rivning av det gamla takmaterialet, ny underlagspapp och ny läkt, nytt ytmaterial, nya plåtbeslag och, om du vill, nya hängrännor och stuprör. Vad som ingår i ditt takbyte står i offerten.`;

const CTA = (name: string, prep: string) =>
  `Boka en kostnadsfri takkontroll för ditt takbyte ${prep} ${name}. Ring 070-154 36 39 eller boka online — vi svarar inom 24 timmar.`;

import { TAKTVATT_COMBO_CONTENT, TAKTVATT_META, taktvattComboTitle } from "./taktvatt-text";

/** De tre indexerade taktvätt × ort-sidorna (thin-combos.ts) får samma korta text som /tjanster/taktvatt (backlog 1cl). */
const taktvattOrt = (prep: string, name: string): ComboOverride => ({
  title: taktvattComboTitle(prep, name),
  description: TAKTVATT_META,
  content: TAKTVATT_COMBO_CONTENT,
});

